export function matchPublicContext(match){
 if(!match||typeof match!=='object'||!Object.hasOwn(competitions,match.competitionId))return null;
 const ids=[match.homeParticipant?.clubId,match.awayParticipant?.clubId];
 const selected=[];
 for(const id of ids)if(typeof id==='string'&&Object.hasOwn(clubs,id)&&!selected.some(c=>c.countryId+'-'+c.clubId===id))selected.push(clubs[id]);
 return {clubs:selected,competitions:[competitions[match.competitionId]]};
}
export function publicClubIdentityCatalog(){return {clubs:Object.values(clubs),clubCrests};}
